const cfg = $input.first().json;

const now = new Date();
const weekEndISO = now.toISOString();
const weekStart = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekStartISO = weekStart.toISOString();

const ghHeaders = {
  'Accept': 'application/vnd.github+json',
  'Authorization': `Bearer ${cfg.githubToken}`,
  'X-GitHub-Api-Version': '2022-11-28',
};

const base = `https://api.github.com/repos/${cfg.repoOwner}/${cfg.repoName}`;

async function getJson(url) {
  const res = await fetch(url, {headers: ghHeaders});
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`GitHub API ${res.status}: ${txt}`);
  }
  return res.json();
}

const commits = await getJson(`${base}/commits?since=${encodeURIComponent(weekStartISO)}&until=${encodeURIComponent(weekEndISO)}&per_page=100`);
const issues = await getJson(`${base}/issues?state=closed&since=${encodeURIComponent(weekStartISO)}&per_page=100`);
const pulls = await getJson(`${base}/pulls?state=closed&sort=updated&direction=desc&per_page=100`);

const mergedPRs = pulls.filter(pr => pr.merged_at && pr.merged_at >= weekStartISO && pr.merged_at <= weekEndISO);
const closedIssues = issues.filter(i => !i.pull_request);

const commitLines = commits.slice(0, 40).map(c => `- ${c.sha.slice(0,7)} ${c.commit.message.split('\n')[0]} (@${c.author?.login || 'unknown'})`);
const issueLines = closedIssues.slice(0, 40).map(i => `- #${i.number}: ${i.title}`);
const prLines = mergedPRs.slice(0, 40).map(pr => `- #${pr.number}: ${pr.title} (@${pr.user?.login || 'unknown'})`);

const language = (cfg.language || 'EN').toUpperCase() === 'FR' ? 'French' : 'English';

const prompt = `You are a senior engineering program assistant.\nWrite a concise weekly development narrative in ${language}.\n\nContext:\n- Repository: ${cfg.repoOwner}/${cfg.repoName}\n- Time window: ${weekStartISO} -> ${weekEndISO}\n- Commits count: ${commits.length}\n- Closed issues count: ${closedIssues.length}\n- Merged PR count: ${mergedPRs.length}\n\nCommits:\n${commitLines.join('\n') || '- none'}\n\nClosed issues:\n${issueLines.join('\n') || '- none'}\n\nMerged PRs:\n${prLines.join('\n') || '- none'}\n\nOutput format:\n1) 3-5 sentence narrative summary\n2) Bullet list: key technical highlights\n3) Bullet list: risks / follow-ups for next week\nKeep it practical and specific.`;

const anthropicRes = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'x-api-key': cfg.anthropicApiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1200,
    messages: [{role: 'user', content: prompt}]
  })
});

if (!anthropicRes.ok) {
  const txt = await anthropicRes.text();
  throw new Error(`Anthropic API ${anthropicRes.status}: ${txt}`);
}

const anthropicJson = await anthropicRes.json();
const summary = anthropicJson?.content?.[0]?.text || 'No summary generated';

return [{
  json: {
    ...cfg,
    weekStartISO,
    weekEndISO,
    commitsCount: commits.length,
    closedIssuesCount: closedIssues.length,
    mergedPRsCount: mergedPRs.length,
    summary,
    slackText: `*Weekly Dev Summary* (${cfg.repoOwner}/${cfg.repoName})\nWindow: ${weekStartISO} → ${weekEndISO}\nCommits: ${commits.length} | Closed issues: ${closedIssues.length} | Merged PRs: ${mergedPRs.length}\n\n${summary}`
  }
}];
